const PARTIES=['PP','PSOE','VOX','SUMAR','ERC','JUNTS','BILDU','PNV','BNG','CCa','UPN'];
const BASE={PP:33.06,PSOE:31.70,VOX:12.39,SUMAR:12.31};
function simulate(data,nat){
  const tot={};PARTIES.forEach(p=>tot[p]=0);const prov=[];
  for(const c of data){
    const listed=PARTIES.reduce((a,p)=>a+c.p[p],0);
    const raw={};PARTIES.forEach(p=>{let v=c.p[p];if(nat[p]!==undefined&&BASE[p])v=v*nat[p]/BASE[p];raw[p]=v});
    const others=Math.max(0,100-listed);
    const sum=PARTIES.reduce((a,p)=>a+raw[p],0)+others;
    const sh={};PARTIES.forEach(p=>sh[p]=raw[p]/sum*100);
    const el=PARTIES.filter(p=>sh[p]>=3);
    const seats={};PARTIES.forEach(p=>seats[p]=0);
    let lastQ=0,lastP=null;
    for(let k=0;k<c.s;k++){let best=null,bv=-1;for(const p of el){const q=sh[p]/(seats[p]+1);if(q>bv){bv=q;best=p}}if(best){seats[best]++;lastQ=bv;lastP=best;}}
    let nq=0,np=null;for(const p of el){const q=sh[p]/(seats[p]+1);if(q>nq){nq=q;np=p}}
    PARTIES.forEach(p=>tot[p]+=seats[p]);prov.push({n:c.n,s:c.s,seats,sh,marg:{win:lastP,lose:np,ratio:lastQ?nq/lastQ:0}});
  }
  return {tot,prov};
}
const SITE_URL='https://juanle-lopez.github.io/Datos29N/';
let mapSel=null,lastProv=null,mapMode='win',mapBuilt=false;
const MODES=[['win','Ganador'],['PP','PP'],['PSOE','PSOE'],['VOX','Vox'],['SUMAR','Sumar'],['air','Escaño en el aire']];
const tileWinner=c=>{let b=null,bs=-1,bsh=-1;for(const p of PARTIES){const k=c.seats[p];if(k>bs||(k===bs&&c.sh[p]>bsh)){b=p;bs=k;bsh=c.sh[p]}}return b};
const clamp01=x=>Math.max(0,Math.min(1,x));
function buildMap(){
  const el=document.getElementById('map');if(!el||mapBuilt)return;mapBuilt=true;
  const names=Object.keys(GEO.p);
  let h=`<svg class="geomap" viewBox="0 0 ${GEO.w} ${GEO.h}" role="group" aria-label="Mapa de España por provincias">`;
  names.forEach(n=>{h+=`<path class="prov" data-n="${n.replace(/"/g,'&quot;')}" d="${GEO.p[n].d}"><title>${n}</title></path>`});
  ['Ceuta','Melilla'].forEach(n=>{const c=GEO.p[n].c;h+=`<circle class="prov mk" data-n="${n}" cx="${c[0]}" cy="${c[1]}" r="7"><title>${n}</title></circle>`});
  const f=GEO.inset;h+=`<rect class="inset" x="${f[0]}" y="${f[1]}" width="${f[2]}" height="${f[3]}" rx="6"/><text class="insl" x="${f[0]+8}" y="${f[1]+16}">Canarias</text><g id="mlab"></g></svg>`;
  el.innerHTML=h;
  el.addEventListener('click',e=>{const t=e.target.closest('.prov');if(!t)return;mapSel=t.dataset.n;paintMap();showInfo();const s=document.getElementById('provsel');if(s)s.value=mapSel});
  document.getElementById('mapmodes').innerHTML=MODES.map(m=>`<button type="button" data-mm="${m[0]}" aria-pressed="${m[0]===mapMode}">${m[1]}</button>`).join('');
  document.getElementById('mapmodes').addEventListener('click',e=>{const b=e.target.closest('[data-mm]');if(!b)return;mapMode=b.dataset.mm;document.querySelectorAll('[data-mm]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));paintMap()});
  const sel=document.getElementById('provsel');
  sel.innerHTML='<option value="">Elige una provincia…</option>'+names.slice().sort((a,b)=>a.localeCompare(b,'es')).map(n=>`<option>${n}</option>`).join('');
  sel.addEventListener('change',()=>{mapSel=sel.value||null;paintMap();showInfo()});
}
function paintMap(){
  if(!lastProv)return;
  const by={};lastProv.forEach(c=>by[c.n]=c);
  let mx=1;if(PARTIES.includes(mapMode))mx=Math.max(...lastProv.map(c=>c.sh[mapMode]));
  document.querySelectorAll('.prov').forEach(p=>{
    const c=by[p.dataset.n];if(!c)return;let fill,close=c.marg.ratio>=0.95&&c.marg.win!==c.marg.lose;
    if(mapMode==='win'){const w=tileWinner(c);const t=clamp01((c.sh[w]-18)/37);fill=`color-mix(in srgb, ${COL[w]||REG} ${Math.round(38+62*t)}%, var(--panel))`}
    else if(mapMode==='air'){const t=clamp01((c.marg.ratio-0.75)/0.25);fill=`color-mix(in srgb, var(--mid) ${Math.round(8+92*t)}%, var(--line))`}
    else{const t=clamp01(c.sh[mapMode]/mx);fill=`color-mix(in srgb, ${COL[mapMode]} ${Math.round(8+92*t)}%, var(--line))`}
    p.style.fill=fill;p.classList.toggle('close',close);p.classList.toggle('sel',p.dataset.n===mapSel);
  });
  const lg=document.getElementById('maplegend');
  if(mapMode==='win')lg.innerHTML='<span>Color = partido con más escaños. Más intenso = más voto del ganador.</span>'+MAIN.map(p=>`<i style="background:${COL[p]}"></i>${NAMES[p]}`).join(' ');
  else if(mapMode==='air')lg.innerHTML='<span>Más cálido = el último escaño está más disputado.</span><b class="grad" style="background:linear-gradient(90deg,var(--line),var(--mid))"></b>';
  else lg.innerHTML=`<span>Voto estimado de ${NAMES[mapMode]}:</span> 0% <b class="grad" style="background:linear-gradient(90deg,var(--line),${COL[mapMode]})"></b> ${fmt(mx)}%`;
  const lab=document.getElementById('mlab');
  lab.innerHTML=lastProv.filter(c=>c.s>=10&&GEO.p[c.n]).map(c=>`<text class="seatn" x="${GEO.p[c.n].c[0]}" y="${GEO.p[c.n].c[1]+5}" text-anchor="middle">${c.s}</text>`).join('');
}
function renderMap(r){
  lastProv=r.prov;buildMap();paintMap();
  const lead=r.prov.filter(c=>c.marg.ratio>=0.95&&c.marg.win!==c.marg.lose).sort((a,b)=>b.marg.ratio-a.marg.ratio);
  document.getElementById('aire').innerHTML=lead.length?`<b>${lead.length} provincias con un escaño en el aire</b> (el siguiente partido llega al 95% o más del cociente del último escaño): `+lead.slice(0,8).map(c=>`${c.n} (${NAMES[c.marg.win]} lo gana por poco frente a ${NAMES[c.marg.lose]})`).join('; ')+(lead.length>8?'…':'')+'.':'Ninguna provincia tiene un último escaño a menos del 5% de cambiar de manos.';
  showInfo();
}
function showInfo(){
  const box=document.getElementById('mapinfo');if(!box||!lastProv)return;
  const c=lastProv.find(x=>x.n===mapSel);
  if(!c){box.innerHTML='<p class="note">Toca una provincia (o elígela en la lista) para ver su reparto.</p>';return}
  const seats=PARTIES.filter(p=>c.seats[p]).sort((a,b)=>c.seats[b]-c.seats[a]);
  const top=PARTIES.slice().sort((a,b)=>c.sh[b]-c.sh[a]).slice(0,4);
  box.innerHTML=`<div class="mi"><h3>${c.n} <small>${c.s} ${c.s===1?'escaño':'escaños'}</small></h3><p>${seats.map(p=>`<span class="dot" style="background:${COL[p]||REG}"></span>${NAMES[p]} <b>${c.seats[p]}</b>`).join(' &nbsp; ')}</p><p class="note">Voto estimado: ${top.map(p=>NAMES[p]+' '+fmt(c.sh[p])+'%').join(' · ')}. ${c.marg.win&&c.marg.win!==c.marg.lose?`Último escaño: ${NAMES[c.marg.win]}; el siguiente es ${NAMES[c.marg.lose]} con el ${Math.round(c.marg.ratio*100)}% de su cociente.`:''}</p></div>`;
}
function renderShare(t){
  const box=document.getElementById('share');if(!box)return;
  const txt=`Mi simulación para el 29N: PP ${t.PP}, PSOE ${t.PSOE}, Vox ${t.VOX}, Sumar ${t.SUMAR} escaños. PP+Vox: ${t.PP+t.VOX}. Pruébalo con tus datos:`;
  const u=encodeURIComponent(SITE_URL),x=encodeURIComponent(txt);
  box.innerHTML=`<span class="lab">Compartir mi resultado</span><div class="sh"><a class="wa" href="https://wa.me/?text=${x}%20${u}">WhatsApp</a><a href="https://t.me/share/url?url=${u}&text=${x}">Telegram</a><a href="https://twitter.com/intent/tweet?text=${x}&url=${u}">X</a><button type="button" id="cp">Copiar texto</button></div><span class="note" id="cpm" aria-live="polite"></span>`;
  document.getElementById('cp').addEventListener('click',async()=>{
    const full=txt+' '+SITE_URL,m=document.getElementById('cpm');
    try{await navigator.clipboard.writeText(full);m.textContent='Copiado.'}catch(e){m.textContent=full}
  });
}
const HORDER=['SUMAR','PSOE','ERC','BILDU','BNG','PNV','JUNTS','CCa','UPN','PP','VOX'];
const HEMI=(function(){
  const n=350,rows=11,r0=.42,R=190,cx=200,cy=200,radii=[];
  for(let i=0;i<rows;i++)radii.push(r0+(1-r0)*i/(rows-1));
  const sr=radii.reduce((a,b)=>a+b,0);let counts=radii.map(r=>Math.round(n*r/sr));
  counts[rows-1]+=n-counts.reduce((a,b)=>a+b,0);
  const seats=[];
  radii.forEach((r,i)=>{for(let k=0;k<counts[i];k++){const th=Math.PI*(1-k/(counts[i]-1));seats.push({x:cx+R*r*Math.cos(th),y:cy-R*r*Math.sin(th),th,r})}});
  seats.sort((a,b)=>b.th-a.th||a.r-b.r);
  return seats;
})();
const hemiState={};
function hemiParties(t){const a=[];HORDER.forEach(p=>{for(let i=0;i<(t[p]||0);i++)a.push(p)});return a}
function renderHemi(id,t,opts){
  const box=document.getElementById(id);if(!box)return;opts=opts||{};
  let st=hemiState[id];
  if(!st){
    let h='<svg viewBox="0 -16 400 228" class="hemi" role="img" aria-label="">';
    h+=`<line x1="200" y1="0" x2="200" y2="200" class="hmaj"/><text x="200" y="-5" text-anchor="middle" class="hmajt">176 = mayoría</text>`;
    HEMI.forEach((s,i)=>{h+=`<circle cx="${s.x.toFixed(1)}" cy="${s.y.toFixed(1)}" r="4.3" style="--i:${i}"/>`});
    h+='</svg>';
    box.innerHTML=h;st=hemiState[id]={circles:[...box.querySelectorAll('circle')],svg:box.querySelector('svg')};
  }
  const a=hemiParties(t);
  st.circles.forEach((c,i)=>{c.setAttribute('class','p-'+(a[i]||'x'))});
  st.svg.setAttribute('aria-label','Hemiciclo de 350 escaños: '+HORDER.filter(p=>t[p]).map(p=>NAMES[p]+' '+t[p]).join(', '));
}
const NAMES={PP:'PP',PSOE:'PSOE',VOX:'Vox',SUMAR:'Sumar',ERC:'ERC',JUNTS:'Junts',BILDU:'EH Bildu',PNV:'PNV',BNG:'BNG',CCa:'CCa',UPN:'UPN'};
const COL={PP:'var(--pp)',PSOE:'var(--psoe)',VOX:'var(--vox)',SUMAR:'var(--sumar)'};
const REG='var(--reg)';
const PRESETS={'2023':{PP:33.06,PSOE:31.70,VOX:12.39,SUMAR:12.31},poll:{PP:32.1,PSOE:26.5,VOX:18.4,SUMAR:9.3}};
const MAIN=['PP','PSOE','VOX','SUMAR'];
const LABEL={PP:'PP',PSOE:'PSOE',VOX:'Vox',SUMAR:'Sumar (+Podemos)'};
let nat={...PRESETS.poll};
const ctls=document.getElementById('ctls');
MAIN.forEach(p=>{
  const d=document.createElement('div');d.className='ctl';
  d.innerHTML=`<label for="r_${p}"><span class="dot" style="background:${COL[p]}"></span>${LABEL[p]}</label><output id="o_${p}"></output><input type="range" id="r_${p}" min="0" max="45" step="0.1"><small id="s_${p}"></small>`;
  ctls.appendChild(d);
  d.querySelector('input').addEventListener('input',e=>{nat[p]=parseFloat(e.target.value);setPressed(null);render()});
});
function setPressed(k){document.querySelectorAll('[data-p]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.p===k)))}
document.querySelectorAll('[data-p]').forEach(b=>b.addEventListener('click',()=>{nat={...PRESETS[b.dataset.p]};setPressed(b.dataset.p);render()}));
const fmt=n=>n.toFixed(1).replace('.',',');
function bloc(title,seats,list){
  const n=list.reduce((a,p)=>a+seats[p],0);
  return `<div class="bloc"><span>${title}</span><b>${n}</b><span class="${n>=176?'ok':'no'}">${n>=176?'Mayoría absoluta':'Faltan '+(176-n)}</span></div>`;
}
function render(){
  const r=simulate(DATA,nat), t=r.tot;
  MAIN.forEach(p=>{document.getElementById('r_'+p).value=nat[p];document.getElementById('o_'+p).textContent=fmt(nat[p])+'%';
    const d=nat[p]-PRESETS['2023'][p];document.getElementById('s_'+p).textContent='23-J: '+fmt(PRESETS['2023'][p])+'%  ('+(d>=0?'+':'')+fmt(d)+')'});
  const order=['PP','PSOE','VOX','SUMAR','ERC','JUNTS','BILDU','PNV','BNG','CCa','UPN'];
  const bar=document.getElementById('bar');bar.querySelectorAll('.seg').forEach(e=>e.remove());
  const mark=document.getElementById('mark');
  order.forEach(p=>{if(!t[p])return;const s=document.createElement('div');s.className='seg';s.style.width=(t[p]/350*100)+'%';s.style.background=COL[p]||REG;s.title=NAMES[p]+': '+t[p];bar.insertBefore(s,mark)});
  mark.style.left=(176/350*100)+'%';
  const total=Object.values(t).reduce((a,b)=>a+b,0);
  bar.setAttribute('aria-label','Reparto de escaños: '+order.filter(p=>t[p]).map(p=>NAMES[p]+' '+t[p]).join(', '));
  document.getElementById('blocs').innerHTML=
    bloc('PP + Vox',t,['PP','VOX'])+
    bloc('PP + Vox + UPN + CCa',t,['PP','VOX','UPN','CCa'])+
    bloc('PSOE + Sumar + socios 2023',t,['PSOE','SUMAR','ERC','JUNTS','BILDU','PNV','BNG','CCa']);
  const base=PRESETS['2023'];
  const A23={PP:137,PSOE:121,VOX:33,SUMAR:31,ERC:7,JUNTS:7,BILDU:6,PNV:5,BNG:1,CCa:1,UPN:1};
  document.getElementById('tp').innerHTML='<tr><th>Partido</th><th>Escaños</th><th>23-J</th><th>Cambio</th></tr>'+
    order.map(p=>{const d=t[p]-A23[p];return `<tr><td><span class="dot" style="background:${COL[p]||REG}"></span> ${NAMES[p]}</td><td class="m">${t[p]}</td><td class="m">${A23[p]}</td><td class="m ${d>0?'up':d<0?'dn':'eq'}">${d>0?'+':''}${d}</td></tr>`}).join('')+
    `<tr><td><b>Total</b></td><td class="m"><b>${total}</b></td><td class="m">350</td><td></td></tr>`;
  document.getElementById('tc').innerHTML='<tr><th>Circunscripción</th><th>Esc.</th><th>PP</th><th>PSOE</th><th>Vox</th><th>Sumar</th><th>Otros</th></tr>'+
    r.prov.map(c=>{const o=c.s-c.seats.PP-c.seats.PSOE-c.seats.VOX-c.seats.SUMAR;return `<tr><td>${c.n}</td><td class="m">${c.s}</td><td class="m">${c.seats.PP}</td><td class="m">${c.seats.PSOE}</td><td class="m">${c.seats.VOX}</td><td class="m">${c.seats.SUMAR}</td><td class="m">${o}</td></tr>`}).join('');
  renderMap(r);renderShare(t);renderHemi('hemi2',t);
}
render();

/* hero: hemiciclo 2023 -> encuestas */
(function(){
  const box=document.getElementById('hemi1');if(!box)return;
  const old=simulate(DATA,PRESETS['2023']).tot,poll=simulate(DATA,PRESETS.poll).tot;
  const lab=document.getElementById('hlab'),hs=document.getElementById('hstats');
  const P=['PP','PSOE','VOX','SUMAR'];
  hs.innerHTML=P.map(p=>`<div class="hs" style="--c:${COL[p]}"><span class="hn">${NAMES[p]}</span><b id="hn_${p}">${old[p]}</b><small id="hd_${p}">23-J</small></div>`).join('');
  renderHemi('hemi1',old);
  const L1='Resultado del 23-J de 2023',L2='Escenario con la media de encuestas (cierre 3-oct) sobre las provincias de 2023. No es una previsión.';
  lab.textContent=L1;
  const start=()=>box.classList.add('on');
  if(REDUCE){start();renderHemi('hemi1',poll);lab.textContent=L2;P.forEach(p=>{document.getElementById('hn_'+p).textContent=poll[p];const d=poll[p]-old[p];document.getElementById('hd_'+p).textContent=(d>0?'+':'')+d+' vs 2023'});return}
  requestAnimationFrame(()=>requestAnimationFrame(start));
  setTimeout(()=>{
    renderHemi('hemi1',poll);lab.textContent=L2;
    const t0=performance.now(),dur=1700;
    (function step(now){const k=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-k,3);
      P.forEach(p=>{document.getElementById('hn_'+p).textContent=Math.round(old[p]+(poll[p]-old[p])*e)});
      if(k<1)requestAnimationFrame(step);else P.forEach(p=>{const d=poll[p]-old[p];document.getElementById('hd_'+p).textContent=(d>0?'+':'')+d+' vs 2023'})})(t0);
  },2200);
})();
